static int dec(const uint8_t*s,size_t n,uint8_t*d,size_t out){return LZ4_decompress_safe((const char*)s,(char*)d,(int)n,(int)out)==(int)out?0:-1;}
static uint8_t*readall(const char*p,size_t*n){FILE*f=fopen(p,"rb");if(!f)return NULL;fseek(f,0,SEEK_END);*n=(size_t)ftell(f);rewind(f);uint8_t*b=malloc(*n);if(!b||fread(b,1,*n,f)!=*n)exit(9);fclose(f);return b;}
int main(int argc,char**argv){
