 if(!s.p||!h)return 3;
 uint8_t*cart=calloc(1,0x400000u);uint8_t*scratch=calloc(1,2048);uint8_t*block=calloc(1,75776);wf_tag_shared_t c;
 int rc=wf_tag_shared_open(&c,rd,&s,(uint32_t)s.n,(uint32_t)strtoul(argv[3],NULL,0),cart,0x400000u,scratch,2048,h,hn,dec,block,75776);
 if(rc==1){
  wf_cropped_atlas_t atlas;uint8_t hdr[2048];unsigned before=calls;
  if(!wf_cropped_atlas_bind(&atlas,c.header,2048,cart,c.memory,h,hn))rc=-99;
  if(wf_tag_shared_read(&c,0,hdr,2048)||memcmp(hdr,c.header,2048)||wf_tag_shared_read(&c,2048,cart,c.memory)||calls!=before)rc=-98;
