    return service_limit(s,field,budget,SERVICE_STEPS,false);
}

/* One state transition only. A QUERY/GET may reserve one future sector even
 * when this physical field has exhausted its FIFO quota. DATA always returns
 * untouched; the caller must later grant an explicit per-field byte quota.
 * A single call does <=1 HIRQ read and <=1 issue/response/clear callback.
 * No copy/hash/consumer action is part of this API. Existing R05 entry points
 * retain their original state count, transfer size and stop behavior. */
bool wp0_cd_stream_control_step(wp0_cd_stream_t *s,uint32_t field){
    return service_limit(s,field,WP0_CD_STREAM_SECTOR_BYTES,1u,true);
}

bool wp0_cd_stream_control_reserve(wp0_cd_stream_t *s,uint32_t field,uint32_t bytes){
    if(!s)return false;
