  p->owner=false;p->retain=false;p->received=0;p->release_field=field;p->phase=WF_TP_RELEASED;return true;
 }
 if(!p->owner||!wp0_cd_stream_stop_request(&p->stream,field))return failure(p);
 p->phase=WF_TP_STOPPING;return true;
}
bool wf_tag_prefetch_stream_released(const wf_tag_prefetch_stream_t*p){return p&&p->phase==WF_TP_RELEASED&&!p->owner;}
static void field_begin(wf_tag_prefetch_stream_t*p,uint32_t field){
 if(!p->field_seen||field!=p->last_field){p->fifo_field_base=p->stream.bytes_copied;p->copied_this_field=0;p->validated_this_field=0;}
 p->field_seen=true;p->last_field=field;p->polls++;
}
bool wf_tag_prefetch_stream_control_ready(const wf_tag_prefetch_stream_t*p,uint32_t field){
 if(!p||!p->owner||p->stream.error||(p->phase!=WF_TP_HEADER&&p->phase!=WF_TP_ENTRY&&p->phase!=WF_TP_PAYLOAD))return false;
 if(p->stream.state==WP0_CD_STREAM_DATA||p->stream.state==WP0_CD_STREAM_OFF||p->stream.state==WP0_CD_STREAM_DONE||p->stream.state==WP0_CD_STREAM_FAILED)return false;
 /* A ready consumer has priority under the heavy admission. Otherwise control
  * can reserve one future GET even when this field's copy quota is exhausted. */
 if(wp0_cd_stream_available(&p->stream)&&(!p->field_seen||field!=p->last_field||p->copied_this_field<2048u))return false;
 return true;
}
bool wf_tag_prefetch_stream_poll_control(wf_tag_prefetch_stream_t*p,uint32_t field){
 if(!p||p->phase==WF_TP_FAILED)return false;
 if(!wf_tag_prefetch_stream_control_ready(p,field))return true;
 field_begin(p,field);
 if(!wp0_cd_stream_control_reserve(&p->stream,field,p->phase==WF_TP_PAYLOAD?8192u:2048u))return failure(p);
 return true;
}
unsigned wf_tag_prefetch_stream_payload_ready(const wf_tag_prefetch_stream_t*p,uint32_t field){
 if(!p||!p->owner||p->phase!=WF_TP_PAYLOAD||p->stream.error)return WF_TP_PAYLOAD_NONE;
 bool same=p->field_seen&&p->last_field==field;
 uint32_t copied=same?p->copied_this_field:0,used=same?p->stream.bytes_copied-p->fifo_field_base:0;
 if(copied>2048u||used>8192u)return WF_TP_PAYLOAD_NONE;
 if(wp0_cd_stream_available(&p->stream))return copied?WF_TP_PAYLOAD_NONE:WF_TP_PAYLOAD_CONSUME;
 return p->stream.state==WP0_CD_STREAM_DATA&&!used?WF_TP_PAYLOAD_FIFO:WF_TP_PAYLOAD_NONE;
}
bool wf_tag_prefetch_stream_poll_payload(wf_tag_prefetch_stream_t*p,uint32_t field,unsigned step){
 if(!p||p->phase==WF_TP_FAILED)return false;
 if(step!=WF_TP_PAYLOAD_FIFO&&step!=WF_TP_PAYLOAD_CONSUME)return false;
 /* A selected short route may become stale, but never turn into another
  * route or heavy stop/validation after its caller rechecks identity. */
 if(wf_tag_prefetch_stream_payload_ready(p,field)!=step)return true;
 field_begin(p,field);
 if(step==WF_TP_PAYLOAD_FIFO){
  uint32_t used=p->stream.bytes_copied-p->fifo_field_base;
  if(used>8192u||!wp0_cd_stream_service_quota(&p->stream,field,8192u-used))return failure(p);
  return wp0_cd_stream_available(&p->stream)>WP0_CD_STREAM_BURST_BYTES?failure(p):true;
 }
 uint32_t n=wp0_cd_stream_available(&p->stream);
 if(n>WP0_CD_STREAM_BURST_BYTES||(n&2047u)||n<2048u||p->copied_this_field||
    p->received>p->extent.bytes||2048u>p->extent.bytes-p->received)return failure(p);
 uint32_t contiguous=0;const uint8_t*src=wp0_cd_stream_peek(&p->stream,&contiguous);
 if(!src||contiguous<2048u)return failure(p);
 uint8_t*dst=p->cart+p->extent.cart_offset+p->received;
 uint32_t hash=wf_tag_prefetch_words_hash(p->prefix_hash,src,2048u);
 if(!wp0_cd_stream_copy(&p->stream,0,dst,2048u)||!wp0_cd_stream_consume(&p->stream,2048u))return failure(p);
 p->prefix_hash=hash;p->received+=2048u;p->copied_this_field=2048u;
 if(p->max_copy_bytes<2048u)p->max_copy_bytes=2048u;
 if(wp0_cd_stream_eof(&p->stream)&&p->received==p->extent.bytes&&!wf_tag_prefetch_stream_stop(p,field,true))return false;
 return true;
}
static bool poll(wf_tag_prefetch_stream_t*p,uint32_t field,bool cooperative){
 if(!p||p->phase==WF_TP_FAILED)return false;
 bool same=p->field_seen&&field==p->last_field;
 if(same&&(!cooperative||p->phase==WF_TP_STOPPING)){p->skipped_same_field++;return true;}
 field_begin(p,field);
 if(p->phase==WF_TP_RELEASED||p->phase==WF_TP_IDLE)return true;
 uint32_t used=p->stream.bytes_copied-p->fifo_field_base;
 if(used>8192u||p->copied_this_field>2048u)return failure(p);
 if(p->phase==WF_TP_STOPPING){int rc=wp0_cd_stream_stop_service_quota(&p->stream,field,8192u-used);if(rc<0)return failure(p);if(rc>0){p->owner=false;p->phase=WF_TP_RELEASED;p->release_field=field;}return true;}
 if(p->phase==WF_TP_VALIDATE){
  if(p->validated_this_field)return true;
  uint32_t before=p->validation.offset;int state=wf_tag_prefetch_validate_step(&p->validation);
  p->validated_this_field=p->validation.offset-before;
  if(state<0)return wf_tag_prefetch_stream_stop(p,field,false);
  if(!state)return true;
  if(!wf_tag_prefetch_validate_finish(&p->validation,p->entry,&p->extent)||!wf_tag_prefetch_layout(&p->extent,0x5c,0x22400000,WF_TP_CART_BYTES,true)||
    overlaps(p->cart+p->extent.cart_offset,p->extent.bytes,p->header,2048)||overlaps(p->cart+p->extent.cart_offset,p->extent.bytes,p->entry,32))return wf_tag_prefetch_stream_stop(p,field,false);
  if(!wp0_cd_stream_restart_async(&p->stream,p->file_fad+p->extent.offset/2048u,p->extent.bytes))return failure(p);
  p->phase=WF_TP_PAYLOAD;p->retain=true;return true;
 }
 if(!wp0_cd_stream_service_quota(&p->stream,field,8192u-used))return failure(p);
 uint32_t n=wp0_cd_stream_available(&p->stream);if(!n)return true;
 if(n>WP0_CD_STREAM_BURST_BYTES)return failure(p);
 uint32_t copy_left=2048u-p->copied_this_field;
 if(!copy_left)return true;
 if(n>copy_left)n=copy_left;
 if(p->phase==WF_TP_HEADER){
  if(n!=2048||!wp0_cd_stream_eof(&p->stream)||!wp0_cd_stream_copy(&p->stream,0,p->header,2048)||!wp0_cd_stream_consume(&p->stream,2048))return failure(p);
  uint32_t at=2048u+p->identity.key*32u;
  if(!wp0_cd_stream_restart_async(&p->stream,p->file_fad+at/2048u,2048))return failure(p);
  p->phase=WF_TP_ENTRY;
 }else if(p->phase==WF_TP_ENTRY){
  uint32_t at=2048u+p->identity.key*32u;
  if(n!=2048||!wp0_cd_stream_eof(&p->stream)||!wp0_cd_stream_copy(&p->stream,at&2047u,p->entry,32)||!wp0_cd_stream_consume(&p->stream,2048))return failure(p);
  if(!wf_tag_prefetch_validate_begin(&p->validation,p->header,p->file_bytes,p->identity.key))return wf_tag_prefetch_stream_stop(p,field,false);
  p->phase=WF_TP_VALIDATE;
 }else if(p->phase==WF_TP_PAYLOAD){
  if((n&2047u)||p->received>p->extent.bytes||n>p->extent.bytes-p->received)return failure(p);
  uint8_t*dst=p->cart+p->extent.cart_offset+p->received;
  uint32_t contiguous=0;const uint8_t*src=wp0_cd_stream_peek(&p->stream,&contiguous);
  if(!src||contiguous<n)return failure(p); /* Sector-aligned ring cannot split a sector. */
  uint32_t hash=wf_tag_prefetch_words_hash(p->prefix_hash,src,n);
  if(!wp0_cd_stream_copy(&p->stream,0,dst,n)||!wp0_cd_stream_consume(&p->stream,n))return failure(p);
  p->prefix_hash=hash;p->received+=n;
  if(wp0_cd_stream_eof(&p->stream)&&p->received==p->extent.bytes&&!wf_tag_prefetch_stream_stop(p,field,true))return false;
 }else return failure(p);
 p->copied_this_field+=n;
 if(n>p->max_copy_bytes)p->max_copy_bytes=n;return true;
}

bool wf_tag_prefetch_stream_poll(wf_tag_prefetch_stream_t*p,uint32_t field){return poll(p,field,false);}
bool wf_tag_prefetch_stream_poll_cooperative(wf_tag_prefetch_stream_t*p,uint32_t field){return poll(p,field,true);}

