#include "wf_tag_prefetch_stream.h"
#include <assert.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
typedef struct {FILE*f;unsigned fad,base,left,last,count,calls,hidden,read_bytes,hirqs,responses,clears,stop_target,transfer_done;bool stall;uint32_t commands[2048];} drive_t;
static uint16_t hirq(void*u){drive_t*d=u;d->hirqs++;uint16_t h=WP0_CD_CMOK|WP0_CD_EHST|WP0_CD_DRDY|0x40;
 if(d->stop_target==WP0_CD_STREAM_END&&d->last==0x6300&&d->transfer_done)h&=~WP0_CD_CMOK;
 if(d->stop_target==WP0_CD_STREAM_HOST_END&&d->last==0x0600)h&=~WP0_CD_EHST;return h;}
static void clear(void*u,uint16_t b){((drive_t*)u)->clears++;(void)b;}
static bool issue(void*u,const wp0_cd_regs_t*r,uint16_t n,uint16_t c){drive_t*d=u;(void)c;if(d->stop_target==WP0_CD_STREAM_END&&r->cr1==0x0600&&(n&WP0_CD_CMOK))return false;d->last=r->cr1;if(d->calls<2048)d->commands[d->calls]=d->last;d->calls++;if((r->cr1&0xff80)==0x1080){d->fad=((r->cr1&127)<<16)|r->cr2;d->left=((r->cr3&127)<<16)|r->cr4;}if(r->cr1==0x6300){d->count=r->cr4;d->transfer_done=0;}return true;}
static bool response(void*u,wp0_cd_regs_t*r){drive_t*d=u;d->responses++;if(d->stall||(d->stop_target==WP0_CD_STREAM_END_WAIT&&d->last==0x0600))return false;*r=(wp0_cd_regs_t){0x0100,0,0,0};if(d->last==0x5100)r->cr4=d->left<4?d->left:4;if(d->last==0x6300)r->cr1=0x4100;if(d->last==0x0600)r->cr2=d->count*1024;return true;}
static uint32_t words(void*u,void*out,uint32_t n){drive_t*d=u;assert(n%512==0);assert(d->left>=n/512);assert(!fseek(d->f,(d->fad-d->base)*2048,SEEK_SET));assert(fread(out,4,n,d->f)==n);d->fad+=n/512;d->left-=n/512;d->read_bytes+=n*4;d->transfer_done+=n*4;return n;}
static int hidden(void*u,uint32_t f,uint32_t n){(void)f;(void)n;((drive_t*)u)->hidden++;return 0;}
static _Alignas(4) uint8_t cart[0x400000],ring[32768],h[2048],entry[32];
static wf_tag_prefetch_stream_t p;
#include "wf_tag_prefetch_wait.h"
typedef int wf_session_t;
static wf_session_t*observed;
static bool identity_still_matches=true;
static unsigned wf_tag_pf_error,publish_count;
static bool matches(wf_session_t*s){(void)s;return identity_still_matches;}
static void publish(void){publish_count++;}
#define prefetch p
#include "adapter_wait_work.inc"
#undef prefetch

#ifdef CONTROL_CAL_RED
#define wf_tag_prefetch_stream_control_ready(p,f) false
#define wf_tag_prefetch_stream_poll_control wf_tag_prefetch_stream_poll_cooperative
#endif
#ifdef S28_RED
#define wf_tag_prefetch_stream_poll_cooperative wf_tag_prefetch_stream_poll
#endif
static void begin(drive_t*d,unsigned bytes){wp0_cd_stream_ops_t ops={d,hirq,clear,issue,response,words,hidden};wf_tag_prefetch_identity_t id={.key=0x87,.generation=7,.paid=0x8000};assert(wf_tag_prefetch_stream_begin(&p,&id,d->base,bytes,cart,sizeof cart,ring,sizeof ring,h,entry,&ops,true));assert(p.owner&&!wf_tag_prefetch_stream_released(&p));}
static void drain(unsigned field){assert(!wf_tag_prefetch_stream_released(&p));for(unsigned i=0;i<300&&!wf_tag_prefetch_stream_released(&p);i++)assert(wf_tag_prefetch_stream_poll(&p,field+i));assert(wf_tag_prefetch_stream_released(&p)&&!p.owner);}
static void service_field(unsigned f,drive_t*d){
 unsigned read=d->read_bytes,received=p.received;
 for(unsigned op=0;op<4&&!wf_tag_prefetch_stream_released(&p);op++){
  unsigned route=wf_tag_prefetch_stream_payload_ready(&p,f),phase=0;bool progress=false;
  route=route==WF_TP_PAYLOAD_FIFO?WF_TP_ROUTE_FIFO:route==WF_TP_PAYLOAD_CONSUME?WF_TP_ROUTE_CONSUME:
    wf_tag_prefetch_stream_control_ready(&p,f)?WF_TP_ROUTE_CONTROL:WF_TP_ROUTE_HEAVY;
  unsigned before=d->read_bytes;
  assert(wait_work(NULL,f,route,&phase,&progress));
  if(route==WF_TP_ROUTE_CONTROL)assert(d->read_bytes==before);
  assert(d->read_bytes-read<=8192&&p.received-received<=2048&&p.validated_this_field<=256);
