 for(;f<6000&&!wf_tag_prefetch_stream_released(&p);f++)service_field(f,&d);
 assert(wf_tag_prefetch_stream_released(&p)&&p.received==p.extent.bytes&&p.retain&&!d.hidden);
 assert(d.read_bytes==p.received+4096u&&p.max_copy_bytes<=2048);
 assert(p.prefix_hash==wf_tag_prefetch_words_hash(2166136261u,cart+p.extent.cart_offset,p.received));
 uint8_t*gold=malloc(p.received);assert(gold);assert(!fseek(d.f,p.extent.offset,SEEK_SET));assert(fread(gold,1,p.received,d.f)==p.received);assert(!memcmp(gold,cart+p.extent.cart_offset,p.received));free(gold);
