  begin(&d,total);f=1;bool found=false;
  for(;f<2000&&!found;f++){
   if(p.phase==WF_TP_PAYLOAD)d.stop_target=target;
   if(p.phase==WF_TP_PAYLOAD&&p.stream.state==target){found=true;break;}
   /* One opportunity per field exposes every control state. */
   unsigned step=wf_tag_prefetch_stream_payload_ready(&p,f);
   if(step)assert(wf_tag_prefetch_stream_poll_payload(&p,f,step));
   else if(wf_tag_prefetch_stream_control_ready(&p,f))assert(wf_tag_prefetch_stream_poll_control(&p,f));
   else assert(wf_tag_prefetch_stream_poll_cooperative(&p,f));
  }
  assert(found);unsigned prefix=p.received;d.stop_target=0;
  assert(wf_tag_prefetch_stream_stop(&p,f,retain));
  for(unsigned stop=0;stop<300&&!wf_tag_prefetch_stream_released(&p);stop++){
   unsigned read=d.read_bytes;assert(wf_tag_prefetch_stream_poll(&p,f+stop));assert(d.read_bytes-read<=8192);
  }
  assert(wf_tag_prefetch_stream_released(&p)&&!p.owner&&p.received==(retain?prefix:0));
 }
 fclose(d.f);puts("18 cancellations: QUERY through EHST, retain/revoke, no hidden reads; quotas and exact bytes PASS");
}

