static bool wait_work(void*u,uint32_t field,unsigned route,unsigned*phase,bool*progress){
 (void)u;
 uint32_t old_phase=prefetch.phase,old_state=prefetch.stream.state,old_commands=prefetch.stream.commands_issued;
 uint32_t old_bytes=prefetch.stream.bytes_copied,old_received=prefetch.received,old_stop=prefetch.stream.stop_stage,old_validated=prefetch.validation.offset;
 if(!matches(observed)&&!wf_tag_prefetch_stream_stop(&prefetch,field,false))wf_tag_pf_error=2;
 /* The route is fixed by admission. Identity loss can revoke it; no short
  * route may become heavy cleanup, FIFO or consumer work of another class. */
 bool ok;
 switch(route){
 case WF_TP_ROUTE_CONTROL:*phase=WF_TP_WAIT_CONTROL;ok=wf_tag_prefetch_stream_poll_control(&prefetch,field);break;
 case WF_TP_ROUTE_FIFO:*phase=WF_TP_WAIT_FIFO;ok=wf_tag_prefetch_stream_poll_payload(&prefetch,field,WF_TP_PAYLOAD_FIFO);break;
 case WF_TP_ROUTE_CONSUME:*phase=WF_TP_WAIT_CONSUME;ok=wf_tag_prefetch_stream_poll_payload(&prefetch,field,WF_TP_PAYLOAD_CONSUME);break;
 case WF_TP_ROUTE_HEAVY:
  *phase=prefetch.phase;
  /* PAYLOAD has only the two explicit short routes. A quota-exhausted
   * consumer must not fall through to combined refill/copy, even when the
   * caller has enough time for heavy work. Hidden drain remains unchanged. */
  ok=prefetch.phase==WF_TP_PAYLOAD?!prefetch.stream.error:wf_tag_prefetch_stream_poll_cooperative(&prefetch,field);break;
 default:*phase=0;ok=false;break;
 }
 *progress=old_phase!=prefetch.phase||old_state!=(uint32_t)prefetch.stream.state||old_commands!=prefetch.stream.commands_issued||
  old_bytes!=prefetch.stream.bytes_copied||old_received!=prefetch.received||old_stop!=prefetch.stream.stop_stage||old_validated!=prefetch.validation.offset;
 if(!ok&&!wf_tag_pf_error)wf_tag_pf_error=0x100u+prefetch.stream.error;
 publish();return ok&&!wf_tag_pf_error;
}

