#include "wf_tag_prefetch_wait.h"
#include <assert.h>
#include <stdio.h>
typedef struct {wf_tag_prefetch_wait_clock_t c;unsigned route,cost,calls;bool busy,fail,progress;} fake_t;
static bool busy(void*u){return ((fake_t*)u)->busy;}
static void clock_read(void*u,wf_tag_prefetch_wait_clock_t*out){*out=((fake_t*)u)->c;}
static unsigned select_route(void*u,uint32_t f){fake_t*x=u;assert(f==x->c.field);return x->route;}
static bool work(void*u,uint32_t f,unsigned route,unsigned*phase,bool*progress){
 fake_t*x=u;assert(route==x->route&&f==x->c.field);x->calls++;*phase=route==WF_TP_ROUTE_FIFO?WF_TP_WAIT_FIFO:route==WF_TP_ROUTE_CONSUME?WF_TP_WAIT_CONSUME:route==WF_TP_ROUTE_CONTROL?WF_TP_WAIT_CONTROL:3;
 *progress=x->progress;x->c.tick=(uint16_t)(x->c.tick+x->cost);
 if((uint16_t)(x->c.tick-x->c.stamp)>=x->c.period){x->c.field++;x->c.stamp=(uint16_t)(x->c.stamp+x->c.period);}
 return !x->fail;
