 const unsigned limits[]={4128,1024,3328,1024};
 for(unsigned i=0;i<4;i++)for(unsigned wrap=0;wrap<2;wrap++)for(unsigned below=0;below<2;below++){
  unsigned budget=limits[i]-below;fake_t x={.c={.field=8,.stamp=wrap?65000:0,.period=13898},.route=routes[i],.cost=limits[i]-128,.busy=true,.progress=true};x.c.tick=(uint16_t)(x.c.stamp+x.c.period-budget);
