  assert(wf_tag_prefetch_wait_service(&ops,&st));assert(x.calls==(below?0:1));assert(!st.field_cross&&!st.deadline_cross);
 }
 fake_t x={.c={8,100,0,13898},.route=WF_TP_ROUTE_FIFO,.cost=2000,.busy=true,.progress=false};
 wf_tag_prefetch_wait_stats_t st={0};wf_tag_prefetch_wait_ops_t ops={&x,busy,clock_read,work,select_route};
 assert(wf_tag_prefetch_wait_service(&ops,&st)&&x.calls==1);
 x.busy=false;x.calls=0;assert(wf_tag_prefetch_wait_service(&ops,&st)&&!x.calls);
 x.busy=true;x.fail=true;assert(!wf_tag_prefetch_wait_service(&ops,&st)&&x.calls==1);
