typedef struct {unsigned commands,reads,hidden,hirqs,responses;uint16_t h,last;unsigned pending_sectors;bool stall,short_read,periodic;wp0_cd_regs_t issued[128];} drive_t;
static uint16_t hirq(void*u){drive_t*d=u;d->hirqs++;return d->h;}
static void clear(void*u,uint16_t b){(void)u;(void)b;}
static bool issue(void*u,const wp0_cd_regs_t*r,uint16_t need,uint16_t bits){drive_t*d=u;(void)bits;if((d->h&need)!=need)return false;d->last=r->cr1;if(d->commands<128)d->issued[d->commands]=*r;d->commands++;if(r->cr1==0x6300)d->pending_sectors=r->cr4;return true;}
static bool response(void*u,wp0_cd_regs_t*r){drive_t*d=u;d->responses++;if(d->stall)return false;*r=(wp0_cd_regs_t){d->periodic?0x2100:0x0100,0,0,0};if(d->last==0x5100)r->cr4=4;if(d->last==0x6300)r->cr1=0x4100;if(d->last==0x0600)r->cr2=d->pending_sectors*1024;return true;}
static uint32_t read_words(void*u,void*out,uint32_t n){drive_t*d=u;if(d->short_read)n--;memset(out,0x63,n*4);d->reads+=n*4;return n;}
static int hidden(void*u,uint32_t f,uint32_t n){(void)f;(void)n;((drive_t*)u)->hidden++;return 0;}
static uint32_t ring[8192];
static wp0_cd_stream_t setup(drive_t*d){memset(d,0,sizeof *d);d->h=WP0_CD_CMOK|WP0_CD_EHST|WP0_CD_DRDY|0x40;wp0_cd_stream_ops_t ops={d,hirq,clear,issue,response,read_words,hidden};wp0_cd_stream_t s;assert(wp0_cd_stream_init(&s,ring,sizeof ring,65536,&ops));return s;}
int main(void){drive_t d;wp0_cd_stream_t s=setup(&d);assert(wp0_cd_stream_start_async(&s,12345));assert(!d.hidden&&!d.commands&&!d.reads);
 unsigned seen=0;
 for(unsigned f=0;f<500&&!wp0_cd_stream_eof(&s);f++){
  unsigned reads=d.reads,checks=d.hirqs;assert(wp0_cd_stream_service(&s,f));assert(d.reads-reads<=8192&&d.hirqs-checks<=12);seen|=1u<<s.state;
  unsigned n=wp0_cd_stream_available(&s);if(n)assert(wp0_cd_stream_consume(&s,n));
 }
 assert(wp0_cd_stream_eof(&s)&&d.reads==65536&&!d.hidden);
 assert(d.issued[0].cr1==0x6000&&d.issued[1].cr1==0x4800&&d.issued[2].cr1==0x3000&&d.issued[3].cr1==(0x1080|(12345>>16)));
 assert(d.issued[3].cr2==12345&&d.issued[3].cr4==32);assert(s.max_service_bytes<=8192);
 /* Readiness delays do one bounded observation, no hidden waits or timeout spin. */
 s=setup(&d);d.h=0;assert(wp0_cd_stream_start_async(&s,12345));assert(wp0_cd_stream_service(&s,20));assert(d.hirqs<=12&&!d.commands);
#ifndef PREFETCH_LEGACY
 const unsigned starts[]={WP0_CD_STREAM_SETUP_LENGTH,WP0_CD_STREAM_SETUP_LENGTH_WAIT,WP0_CD_STREAM_SETUP_LENGTH_EVENT,WP0_CD_STREAM_SETUP_RESET,WP0_CD_STREAM_SETUP_RESET_WAIT,WP0_CD_STREAM_SETUP_RESET_EVENT,WP0_CD_STREAM_SETUP_CONNECT,WP0_CD_STREAM_SETUP_CONNECT_WAIT,WP0_CD_STREAM_SETUP_CONNECT_EVENT};
 for(unsigned i=0;i<sizeof starts/sizeof *starts;i++){
  s=setup(&d);assert(wp0_cd_stream_start_async(&s,12345));s.state=starts[i];assert(wp0_cd_stream_stop_request(&s,100));int rc=0;
  for(unsigned f=100;!rc&&f<400;f++)rc=wp0_cd_stream_stop_service(&s,f);
  assert(rc==1&&s.state==WP0_CD_STREAM_OFF&&s.stop_stage==8&&!d.hidden&&!d.reads);
  for(unsigned c=0;c<d.commands;c++)assert((d.issued[c].cr1&0xff00)!=0x1000); /* Never start PLAY after AB. */
 }
 s=setup(&d);assert(wp0_cd_stream_start_async(&s,12345));s.state=WP0_CD_STREAM_SETUP_LENGTH_WAIT;d.stall=true;
 assert(wp0_cd_stream_stop_request(&s,100));assert(wp0_cd_stream_stop_service(&s,399)==0);assert(wp0_cd_stream_stop_service(&s,400)==-1);
#endif
 s=setup(&d);assert(!wp0_cd_stream_start_async(&s,0));assert(!d.commands&&!d.hidden);
 s=setup(&d);assert(wp0_cd_stream_start_async(&s,12345));d.h|=WP0_CD_DCHG;assert(!wp0_cd_stream_service(&s,0)&&!d.commands);
